import math
from solution import intersection
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# ---- obviously-correct reference model derived from SPEC ----
def _is_prime_ref(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    r = math.isqrt(n)
    f = 3
    while f <= r:
        if n % f == 0:
            return False
        f += 2
    return True


def _expected_ref(interval1, interval2):
    a1, b1 = interval1
    a2, b2 = interval2
    lo = max(a1, a2)
    hi = min(b1, b2)
    if lo > hi:
        return "NO"
    length = hi - lo
    return "YES" if _is_prime_ref(length) else "NO"


def _mk_interval(s, e):
    # enforce spec assumption start <= end
    if s <= e:
        return (s, e)
    return (e, s)


# ---- explicit examples from SPEC ----
def test_spec_example_touching_single_point():
    assert intersection((1, 2), (2, 3)) == "NO"


def test_spec_example_negative():
    assert intersection((-1, 1), (0, 4)) == "NO"


def test_spec_example_prime_length_2():
    assert intersection((-3, -1), (-5, 5)) == "YES"


def test_spec_doc_example_length_1_not_prime():
    # (1,3),(2,4) -> (2,3) length 1 -> not prime
    assert intersection((1, 3), (2, 4)) == "NO"


# ---- small explicit boundaries derived from SPEC ----
def test_identical_intervals_length_0():
    assert intersection((5, 5), (5, 5)) == "NO"  # length 0


def test_identical_intervals_length_1():
    assert intersection((0, 1), (0, 1)) == "NO"  # length 1 not prime


def test_identical_intervals_length_2_prime():
    assert intersection((0, 2), (0, 2)) == "YES"  # length 2 prime


def test_identical_intervals_length_3_prime():
    assert intersection((0, 3), (0, 3)) == "YES"  # length 3 prime


def test_identical_intervals_length_4_not_prime():
    assert intersection((0, 4), (0, 4)) == "NO"


def test_disjoint_returns_no():
    assert intersection((1, 2), (5, 6)) == "NO"


def test_disjoint_reversed_returns_no():
    assert intersection((5, 6), (1, 2)) == "NO"


def test_fully_contained_prime():
    # (0,10) contains (3,5): intersection (3,5) length 2 -> YES
    assert intersection((0, 10), (3, 5)) == "YES"


def test_fully_contained_not_prime():
    # (0,10) contains (3,7): length 4 -> NO
    assert intersection((0, 10), (3, 7)) == "NO"


def test_touching_at_endpoint_length_zero():
    # closed intervals touching at 2: intersection (2,2) length 0 -> NO
    assert intersection((1, 2), (2, 3)) == "NO"
    assert intersection((2, 3), (1, 2)) == "NO"


def test_just_disjoint_by_one():
    # (1,2),(3,4) do not intersect -> NO
    assert intersection((1, 2), (3, 4)) == "NO"


def test_negative_prime_length():
    # (-10,-2) & (-5,-3): intersection (-5,-3) length 2 -> YES
    assert intersection((-10, -2), (-5, -3)) == "YES"


def test_huge_composite_length_must_not_crash():
    # length = 10**400, composite (even), spec requires "NO", not exception
    assert intersection((0, 10**400), (0, 10**400)) == "NO"


def test_huge_disjoint_must_not_crash():
    assert intersection((0, 10**400), (10**400 + 1, 10**400 + 10)) == "NO"


def test_huge_prime_length():
    # length 2 with huge endpoints: intersection length 2 -> YES
    big = 10**400
    assert intersection((big, big + 2), (big, big + 2)) == "YES"


# ---- property-based tests ----
@given(
    a1=st.integers(min_value=-200, max_value=200),
    b1=st.integers(min_value=-200, max_value=200),
    a2=st.integers(min_value=-200, max_value=200),
    b2=st.integers(min_value=-200, max_value=200),
)
def test_property_equivalence_to_reference(a1, b1, a2, b2):
    i1 = _mk_interval(a1, b1)
    i2 = _mk_interval(a2, b2)
    assert intersection(i1, i2) == _expected_ref(i1, i2)


@given(
    a1=st.integers(min_value=-200, max_value=200),
    b1=st.integers(min_value=-200, max_value=200),
    a2=st.integers(min_value=-200, max_value=200),
    b2=st.integers(min_value=-200, max_value=200),
)
def test_property_commutative(a1, b1, a2, b2):
    i1 = _mk_interval(a1, b1)
    i2 = _mk_interval(a2, b2)
    assert intersection(i1, i2) == intersection(i2, i1)


@given(
    a1=st.integers(min_value=-50, max_value=50),
    b1=st.integers(min_value=-50, max_value=50),
    a2=st.integers(min_value=-50, max_value=50),
    b2=st.integers(min_value=-50, max_value=50),
)
def test_property_output_domain(a1, b1, a2, b2):
    i1 = _mk_interval(a1, b1)
    i2 = _mk_interval(a2, b2)
    assert intersection(i1, i2) in ("YES", "NO")


@given(
    s=st.integers(min_value=-200, max_value=200),
    length=st.integers(min_value=0, max_value=50),
    shift=st.integers(min_value=-200, max_value=200),
)
def test_property_identical_intervals_match_primality_of_length(s, length, shift):
    # intersection of identical intervals has length == interval length
    i = (s, s + length)
    expected = "YES" if _is_prime_ref(length) else "NO"
    assert intersection(i, i) == expected


@given(
    a1=st.integers(min_value=-100, max_value=100),
    b1=st.integers(min_value=-100, max_value=100),
    gap=st.integers(min_value=1, max_value=20),
)
def test_property_disjoint_always_no(a1, b1, gap):
    i1 = _mk_interval(a1, b1)
    hi = max(i1)
    # second interval strictly above first
    i2 = (hi + gap, hi + gap + 5)
    assert intersection(i1, i2) == "NO"
    assert intersection(i2, i1) == "NO"


@given(
    lo=st.integers(min_value=-100, max_value=100),
    length=st.integers(min_value=0, max_value=30),
)
def test_property_length_zero_or_one_never_yes(lo, length):
    # force intersection length 0 or 1 -> must be NO
    assume(length in (0, 1))
    i1 = (lo, lo + 10)
    # craft i2 so intersection is (lo, lo+length) when possible
    i2 = (lo, lo + length)
    # ensure overlap is exactly length (i2 inside i1 requires length<=10)
    assume(length <= 10)
    assert intersection(i1, i2) == "NO"
